"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[18039],{3331:(e,s,t)=>{t.d(s,{R:()=>r,x:()=>o});var i=t(36672);const n={},a=i.createContext(n);function r(e){const s=i.useContext(a);return i.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function o(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),i.createElement(a.Provider,{value:s},e.children)}},37717:(e,s,t)=>{t.r(s),t.d(s,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>i,toc:()=>u});const i=JSON.parse('{"id":"2023/04/07","title":"2023-04-07","description":"Si nous perdons l\'Internet Archive, nous sommes foutus","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/2023/04/07.md","sourceDirName":"2023/04","slug":"/2023/04/07","permalink":"/fr/2023/04/07","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/fr/docusaurus-plugin-content-docs//current/2023/04/07.md","tags":[],"version":"current","frontMatter":{"localized_date":"7 avril 2023","top_news":"Si nous perdons l\'Internet Archive, nous sommes foutus"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-08","permalink":"/fr/2023/04/08"},"next":{"title":"2023-04-06","permalink":"/fr/2023/04/06"}}');var n=t(23420),a=t(3331);const r={localized_date:"7 avril 2023",top_news:"Si nous perdons l'Internet Archive, nous sommes foutus"},o="2023-04-07",l={},u=[{value:"Si nous perdons l&#39;Internet Archive, nous sommes foutus",id:"si-nous-perdons-linternet-archive-nous-sommes-foutus",level:2},{value:"Chrome ships WebGPU",id:"chrome-ships-webgpu",level:2},{value:"Show Discussion Service : Tabby - Un copilote GitHub auto-h\xe9berg\xe9",id:"show-discussion-service--tabby---un-copilote-github-auto-h\xe9berg\xe9",level:2},{value:"Les employ\xe9s de Tesla ont partag\xe9 des images provenant des cam\xe9ras des voitures, y compris des &quot;sc\xe8nes d&#39;intimit\xe9&quot;",id:"les-employ\xe9s-de-tesla-ont-partag\xe9-des-images-provenant-des-cam\xe9ras-des-voitures-y-compris-des-sc\xe8nes-dintimit\xe9",level:2},{value:"Expliqu\xe9 simplement : Comment fonctionne le TPG ?",id:"expliqu\xe9-simplement--comment-fonctionne-le-tpg-",level:2},{value:"La conception de syst\xe8mes et le co\xfbt de la complexit\xe9 architecturale (2013)",id:"la-conception-de-syst\xe8mes-et-le-co\xfbt-de-la-complexit\xe9-architecturale-2013",level:2},{value:"Defamed by ChatGPT",id:"defamed-by-chatgpt",level:2},{value:"Master Plan Part 3",id:"master-plan-part-3",level:2},{value:"Les employ\xe9s de Tesla ont partag\xe9 des images sensibles enregistr\xe9es par les voitures des clients",id:"les-employ\xe9s-de-tesla-ont-partag\xe9-des-images-sensibles-enregistr\xe9es-par-les-voitures-des-clients",level:2},{value:"Buck2 : Notre syst\xe8me de construction open source",id:"buck2--notre-syst\xe8me-de-construction-open-source",level:2},{value:"Mariadb.com est mort, vive MariaDB.org",id:"mariadbcom-est-mort-vive-mariadborg",level:2},{value:"Show Discussion Service : Pomodoro, une application web adapt\xe9e aux TDAH",id:"show-discussion-service--pomodoro-une-application-web-adapt\xe9e-aux-tdah",level:2},{value:"Meta lance un nouvel outil de segmentation de photos bas\xe9 sur l&#39;IA pour tout le monde",id:"meta-lance-un-nouvel-outil-de-segmentation-de-photos-bas\xe9-sur-lia-pour-tout-le-monde",level:2},{value:"Ce qui se passe en cas de fuite d&#39;informations d&#39;identification AWS et comment AWS minimise les d\xe9g\xe2ts",id:"ce-qui-se-passe-en-cas-de-fuite-dinformations-didentification-aws-et-comment-aws-minimise-les-d\xe9g\xe2ts",level:2},{value:"Gource - Animez votre historique Git",id:"gource---animez-votre-historique-git",level:2},{value:"Show Discussion Service : G\xe9n\xe9rer des id\xe9es de startups bas\xe9es sur les commentaires Discussion Service",id:"show-discussion-service--g\xe9n\xe9rer-des-id\xe9es-de-startups-bas\xe9es-sur-les-commentaires-discussion-service",level:2},{value:"DevOps utilise un mod\xe8le de capacit\xe9, pas un mod\xe8le de maturit\xe9",id:"devops-utilise-un-mod\xe8le-de-capacit\xe9-pas-un-mod\xe8le-de-maturit\xe9",level:2},{value:"L&#39;augmentation de la capacit\xe9 du r\xe9seau \xe9lectrique n&#39;est pas une t\xe2che simple.",id:"laugmentation-de-la-capacit\xe9-du-r\xe9seau-\xe9lectrique-nest-pas-une-t\xe2che-simple",level:2},{value:"Annonce de WCGI : WebAssembly et CGI",id:"annonce-de-wcgi--webassembly-et-cgi",level:2},{value:"JSON vs. XML",id:"json-vs-xml",level:2},{value:"Site web h\xe9berg\xe9 sur un serveur Linux vieux de 24 ans.",id:"site-web-h\xe9berg\xe9-sur-un-serveur-linux-vieux-de-24-ans",level:2},{value:"Est-ce ma faute si vous ne pouvez pas supporter la v\xe9rit\xe9 ? (2019)",id:"est-ce-ma-faute-si-vous-ne-pouvez-pas-supporter-la-v\xe9rit\xe9--2019",level:2},{value:"Les cordes en do et ma lente descente vers la folie",id:"les-cordes-en-do-et-ma-lente-descente-vers-la-folie",level:2},{value:"MutexProtected : Un mod\xe8le C++ pour une concurence plus facile",id:"mutexprotected--un-mod\xe8le-c-pour-une-concurence-plus-facile",level:2},{value:"Clarence Thomas et le milliardaire",id:"clarence-thomas-et-le-milliardaire",level:2},{value:"La faible composabilit\xe9 de Rust",id:"la-faible-composabilit\xe9-de-rust",level:2},{value:"Rep\xe9rer et \xe9viter la fragmentation du tas dans les applications Rust",id:"rep\xe9rer-et-\xe9viter-la-fragmentation-du-tas-dans-les-applications-rust",level:2},{value:"Faites attention \xe0 ce que vous testez ou d\xe9ployez sur Vercel",id:"faites-attention-\xe0-ce-que-vous-testez-ou-d\xe9ployez-sur-vercel",level:2},{value:"Linux 6.4 apporte des ajouts Apple M2 pour les MacBook et Mac Mini 2022",id:"linux-64-apporte-des-ajouts-apple-m2-pour-les-macbook-et-mac-mini-2022",level:2},{value:"Illustrations de trains de maintenance japonais &quot;invisibles&quot; qui ne fonctionnent que la nuit",id:"illustrations-de-trains-de-maintenance-japonais-invisibles-qui-ne-fonctionnent-que-la-nuit",level:2}];function d(e){const s={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(s.header,{children:(0,n.jsx)(s.h1,{id:"2023-04-07",children:"2023-04-07"})}),"\n",(0,n.jsx)(s.h2,{id:"si-nous-perdons-linternet-archive-nous-sommes-foutus",children:"Si nous perdons l'Internet Archive, nous sommes foutus"}),"\n",(0,n.jsxs)(s.p,{children:["(Original) (",(0,n.jsx)(s.a,{href:"https://www.sbstatesman.com/2023/04/04/if-we-lose-the-internet-archive-were-screwed/",children:"https://www.sbstatesman.com/2023/04/04/if-we-lose-the-internet-archive-were-screwed/"}),").\nL'Internet Archive, qui se d\xe9crit comme \"une biblioth\xe8que \xe0 but non lucratif de millions de livres, de films, de logiciels, de musique, de sites web et bien d'autres choses encore\", a \xe9t\xe9 poursuivi par quatre soci\xe9t\xe9s d'\xe9dition pour violation des droits d'auteur, et un juge f\xe9d\xe9ral a statu\xe9 en faveur des \xe9diteurs. Cependant, l'Internet Archive fait appel de cette d\xe9cision, qui, selon certains, constitue fondamentalement une attaque contre des services publics financ\xe9s par le contribuable, men\xe9e par des entreprises et des particuliers. Les critiques soutiennent que la fermeture de la Biblioth\xe8que nationale d'urgence, qui a mis gratuitement \xe0 disposition des livres prot\xe9g\xe9s par le droit d'auteur pendant la pand\xe9mie de COVID-19, est bien plus d\xe9sastreuse pour la classe ouvri\xe8re que l'acc\xe8s aux livres ne pourra jamais l'\xeatre. Si l'appel est rejet\xe9, les \xeatres humains perdront plus de connaissances que la biblioth\xe8que d'Alexandra n'en a jamais contenu."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35468753",children:"Discussion Service"}),".\nLes utilisateurs de Discussion Service d\xe9battent des lois sur le droit d'auteur et de la pr\xe9servation de la culture. Les batailles juridiques soul\xe8vent des questions sur la l\xe9gitimit\xe9 des droits d'auteur et les monopoles gouvernementaux. Certains appellent \xe0 une meilleure gouvernance pour encourager le travail et \xe0 des dur\xe9es de droits d'auteur plus courtes. La perte de l'AI pourrait r\xe9\xe9crire l'histoire, soulignant l'importance de la pr\xe9servation des connaissances. Il est sugg\xe9r\xe9 de cr\xe9er une nouvelle entit\xe9 ou de cesser les dons en raison du comportement risqu\xe9 de l'AI. La biblioth\xe8que nationale d'urgence est consid\xe9r\xe9e comme inattendue et b\xe9n\xe9fique, mais les dirigeants de l'AI ont la responsabilit\xe9 de pr\xe9server l'histoire."]}),"\n",(0,n.jsx)(s.h2,{id:"chrome-ships-webgpu",children:"Chrome ships WebGPU"}),"\n",(0,n.jsxs)(s.p,{children:["(",(0,n.jsx)(s.a,{href:"https://developer.chrome.com/blog/webgpu-release/",children:"https://developer.chrome.com/blog/webgpu-release/"}),").\nChrome lance WebGPU, une nouvelle API graphique web offrant des graphiques 3D am\xe9lior\xe9s et des calculs parall\xe8les sur ChromeOS, macOS et Windows, afin d'offrir un acc\xe8s aux capacit\xe9s avanc\xe9es du GPU et une programmation efficace avec la plateforme web. WebGPU est con\xe7ue avec une API JavaScript idiomatique, une int\xe9gration avec les promesses et des messages d'erreur de qualit\xe9, et elle constitue une base pour de futures am\xe9liorations, telles que l'acc\xe8s aux c\u0153urs de shaders pour plus d'optimisations de l'apprentissage automatique, et une plus grande ergonomie dans WGSL. WebGPU est le r\xe9sultat d'un effort de collaboration de 6 ans du groupe communautaire \"GPU pour le Web\" du W3C, avec des contributions de Mozilla, Apple, Intel et Microsoft. Les plateformes ChromeOS, Windows et macOS peuvent prendre en charge le WebGPU, tandis que Linux, Android et d'autres plateformes \xe9tendront cette prise en charge dans un avenir proche. Les biblioth\xe8ques WebGL les plus populaires, telles que Babylon.js, PlayCanvas et TensorFlow.js, offrent d\xe9j\xe0 une certaine prise en charge du WebGPU ou y travaillent. Pour en savoir plus sur le WebGPU, vous pouvez consulter les sp\xe9cifications du W3C, la documentation MDN, des exemples, GPU compute, etc."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35465729",children:"Discussion Service"}),".\nChrome a lanc\xe9 WebGPU, qui promet des am\xe9liorations par rapport \xe0 WebGL. WebGPU change la donne et apporte des contributions positives ; les avis divergent quant \xe0 la priorit\xe9 \xe0 accorder aux GPU de bureau ou mobiles. Les utilisateurs discutent des moyens de limiter les fonctionnalit\xe9s du navigateur qui laissent filtrer des informations et d'emp\xeacher la prise d'empreintes digitales. L'utilisation malveillante potentielle pour le minage de crypto-monnaie suscite des inqui\xe9tudes. Web3DSurvey suit les caract\xe9ristiques et les limites li\xe9es au WebGPU. Le potentiel d'adoption du WebGPU suscite l'enthousiasme, malgr\xe9 les inqui\xe9tudes li\xe9es aux limitations par rapport \xe0 des technologies graphiques plus performantes."]}),"\n",(0,n.jsx)(s.h2,{id:"show-discussion-service--tabby---un-copilote-github-auto-h\xe9berg\xe9",children:"Show Discussion Service : Tabby - Un copilote GitHub auto-h\xe9berg\xe9"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://github.com/TabbyML/tabby",children:"Original"}),".\nTabbyML a publi\xe9 Tabby, une alternative auto-h\xe9berg\xe9e \xe0 GitHub Copilot qui est open-source et on-prem. Elle se caract\xe9rise par un confinement autonome, sans besoin d'un SGBD ou d'un service en nuage, une interface Web pour la visualisation et les mod\xe8les de configuration et MLOps, une interface OpenAPI, et une int\xe9gration facile avec l'infrastructure existante. Les d\xe9veloppeurs peuvent utiliser l'image docker pour faciliter le d\xe9ploiement, et TabbyML prend en charge les GPU grand public avec le chargement de poids FP-16 et d'autres optimisations. Son serveur FastAPI int\xe8gre une documentation OpenAPI de l'API HTTP."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35470915",children:"Discussion Service"}),".\nTabby, une alternative GitHub Copilot auto-h\xe9berg\xe9e, offre un contr\xf4le total sur les donn\xe9es et la confidentialit\xe9 tout en affinant les mod\xe8les. Elle permet de gagner du temps, mais soul\xe8ve des questions en mati\xe8re de protection de la vie priv\xe9e. Les probl\xe8mes de confidentialit\xe9 de GitHub sont exag\xe9r\xe9s et Copilot a ses limites. TabbyML g\xe9n\xe8re du code standard et soul\xe8ve des questions sur la protection de la propri\xe9t\xe9 intellectuelle du code. La version alpha de Tabby est populaire malgr\xe9 l'absence de vitrine professionnelle et de preuves \xe0 l'appui. Copilot pr\xe9dit le code avec pr\xe9cision mais a des limites et peut sugg\xe9rer du mauvais code. Certains utilisateurs sugg\xe8rent une version auto-h\xe9berg\xe9e de Copilot et un changement de nom pour un meilleur r\xe9f\xe9rencement."]}),"\n",(0,n.jsx)(s.h2,{id:"les-employ\xe9s-de-tesla-ont-partag\xe9-des-images-provenant-des-cam\xe9ras-des-voitures-y-compris-des-sc\xe8nes-dintimit\xe9",children:'Les employ\xe9s de Tesla ont partag\xe9 des images provenant des cam\xe9ras des voitures, y compris des "sc\xe8nes d\'intimit\xe9"'}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://arstechnica.com/tech-policy/2023/04/tesla-workers-shared-images-from-car-cameras-including-scenes-of-intimacy/",children:"Original"}),'.\nDes employ\xe9s de Tesla auraient partag\xe9 des vid\xe9os et des images prises par les cam\xe9ras des voitures des clients par le biais d\'un syst\xe8me de messagerie interne, dont le contenu \xe9tait "parfois tr\xe8s invasif". Bien que Tesla affirme que les cam\xe9ras embarqu\xe9es sont "con\xe7ues d\xe8s le d\xe9part pour prot\xe9ger la vie priv\xe9e", les employ\xe9s avaient facilement acc\xe8s aux images produites par les cam\xe9ras et partageaient le contenu "librement". Des sc\xe8nes intimes ne pr\xe9sentant pas de nudit\xe9, ainsi que "certaines pi\xe8ces de linge et certains articles de bien-\xeatre sexuel" figuraient parmi les \xe9l\xe9ments partag\xe9s. Toutefois, certains anciens employ\xe9s ont affirm\xe9 qu\'il s\'agissait d\'un partage l\xe9gitime \xe0 des fins professionnelles. Par ailleurs, certaines images auraient \xe9t\xe9 largement partag\xe9es et largement visionn\xe9es, y compris par la direction.']}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35471826",children:"Discussion Service"}),".\nLes utilisateurs discutent de la duplication de l'article et des directives du site sur la soumission de sources originales. Aucun commentaire pertinent sur le sujet de Tesla partageant des images de cam\xe9ras de voiture, y compris des \"sc\xe8nes d'intimit\xe9\"."]}),"\n",(0,n.jsx)(s.h2,{id:"expliqu\xe9-simplement--comment-fonctionne-le-tpg-",children:"Expliqu\xe9 simplement : Comment fonctionne le TPG ?"}),"\n",(0,n.jsxs)(s.p,{children:["(Original) (",(0,n.jsx)(s.a,{href:"https://confusedbit.dev/posts/how_does_gpt_work/",children:"https://confusedbit.dev/posts/how_does_gpt_work/"}),").\nL'article traite du processus qui sous-tend le GPT-3 et de la mani\xe8re dont il est utilis\xe9 pour les conversations en langage naturel gr\xe2ce \xe0 l'int\xe9gration de mots et \xe0 des mod\xe8les probabilistes. Ses points forts sont la g\xe9n\xe9ration de texte et l'encha\xeenement d'id\xe9es logiques, mais il est limit\xe9 par les fausses informations et les restrictions d'entr\xe9e. Il existe des similitudes et des diff\xe9rences avec la structure du cerveau humain, y compris les capacit\xe9s linguistiques limit\xe9es du GPT et l'absence d'apprentissage continu. L'article soul\xe8ve \xe9galement des questions de conscience et des inqui\xe9tudes concernant la perte d'emploi, mais note que le TPG ne peut pas nuire \xe0 lui seul. Toutefois, la prudence est de mise pour la poursuite du d\xe9veloppement de l'IA, et les experts recherchent des moyens de pr\xe9venir les cons\xe9quences n\xe9gatives. Les comp\xe9tences techniques et l'esprit d'entreprise seront pr\xe9cieux, car les cons\xe9quences du TPG restent encore incertaines."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35466201",children:"Discussion Service"}),".\nLes experts de Hacker News d\xe9battent des capacit\xe9s et des limites des mod\xe8les de langage de l'IA, notamment ChatGPT et GPT-4. Certains mettent en garde contre l'attribution \xe0 des machines de propri\xe9t\xe9s semblables \xe0 celles de l'homme, alors que ChatGPT produit des textes pr\xe9cis et adapt\xe9s au contexte, ce qui est un \xe9l\xe9ment de l'intelligence artificielle. D\xe9bat sur la pertinence du sc\xe9nario de la chambre chinoise et sur la nature de l'intelligence et de la conscience. L'attention est port\xe9e sur les capacit\xe9s pratiques et l'innovation, la pertinence des transformateurs et les limites des donn\xe9es d'entra\xeenement. Les sceptiques notent que le GPT-4 ne dispose pas des m\xe9canismes de r\xe9troaction des cerveaux biologiques, bien qu'il produise des textes de type humain."]}),"\n",(0,n.jsx)(s.h2,{id:"la-conception-de-syst\xe8mes-et-le-co\xfbt-de-la-complexit\xe9-architecturale-2013",children:"La conception de syst\xe8mes et le co\xfbt de la complexit\xe9 architecturale (2013)"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://dspace.mit.edu/handle/1721.1/79551",children:"Original"}),".\nLe message d'erreur ",(0,n.jsx)(s.code,{children:"HTTP Status 429 - Too Many Requests"})," indique que l'utilisateur a envoy\xe9 un grand nombre de requ\xeates en peu de temps."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35470905",children:"Discussion Service"}),".\nL'article traite de la conception des syst\xe8mes et du co\xfbt de la complexit\xe9 architecturale. Les utilisateurs partagent leurs exp\xe9riences personnelles avec les fournisseurs de services en nuage et la compr\xe9hension des syst\xe8mes complexes. Les commentaires soulignent l'importance de la simplicit\xe9, d'une bonne documentation et d'une r\xe9flexion prospective. Les avantages et les d\xe9fis de l'architecture logicielle, ainsi que l'\xe9quilibre entre simplicit\xe9 et complexit\xe9, sont d\xe9battus par les experts. La d\xe9finition de la complexit\xe9 dans les syst\xe8mes logiciels est \xe9galement discut\xe9e."]}),"\n",(0,n.jsx)(s.h2,{id:"defamed-by-chatgpt",children:"Defamed by ChatGPT"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://jonathanturley.org/2023/04/06/defamed-by-chatgpt-my-own-bizarre-experience-with-artificiality-of-artificial-intelligence/",children:"Original"}),".\nN/A."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35468540",children:"Discussion Service"}),".\nLa diffamation g\xe9n\xe9r\xe9e par l'IA repr\xe9sente un risque important, et ChatGPT fait l'objet d'un examen minutieux en raison de sa responsabilit\xe9 potentielle. Les utilisateurs d\xe9battent de la responsabilit\xe9 de ses r\xe9sultats et sugg\xe8rent de maintenir une norme de diligence. Les questions de responsabilit\xe9 des voitures autonomes sont \xe9galement abord\xe9es, ainsi que les implications juridiques de ChatGPT en tant qu'outil de recherche de conseils m\xe9dicaux et juridiques. Des pr\xe9occupations concernant la pr\xe9cision des mod\xe8les linguistiques et l'utilisation \xe9thique des donn\xe9es personnelles ont \xe9galement \xe9t\xe9 soulev\xe9es. La fiabilit\xe9 de ChatGPT et la propagation de fausses informations ont \xe9t\xe9 critiqu\xe9es, ce qui a donn\xe9 lieu \xe0 des appels en faveur de clauses de non-responsabilit\xe9 et d'accords contraignants en mati\xe8re de conditions de service. L'intersection de la technologie et de la soci\xe9t\xe9 est au c\u0153ur de ce billet, avec les d\xe9bats juridiques en cours sur la responsabilit\xe9 des r\xe9sultats g\xe9n\xe9r\xe9s par l'IA."]}),"\n",(0,n.jsx)(s.h2,{id:"master-plan-part-3",children:"Master Plan Part 3"}),"\n",(0,n.jsxs)(s.p,{children:["(",(0,n.jsx)(s.a,{href:"https://www.tesla.com/blog/master-plan-part-3",children:"https://www.tesla.com/blog/master-plan-part-3"}),").\nTesla publie la troisi\xe8me partie de son plan directeur, qui propose une voie vers une \xe9conomie \xe9nerg\xe9tique mondiale durable gr\xe2ce \xe0 l'\xe9lectrification et \xe0 la production et au stockage d'\xe9lectricit\xe9, avec des hypoth\xe8ses, des sources et des calculs d\xe9taill\xe9s \xe0 l'appui de la proposition. Les lecteurs sont invit\xe9s \xe0 apporter leur contribution et \xe0 participer \xe0 la conversation. Tesla fournit \xe9galement le profil de la demande am\xe9ricaine enti\xe8rement \xe9lectrifi\xe9e utilis\xe9 dans la mod\xe9lisation."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35462378",children:"Discussion Service"}),".\nLe plan directeur de Tesla, partie 3, retient l'attention sur Hacker News avec des discussions sur la vie sans combustible fossile, la faisabilit\xe9 des VE, l'investissement dans les \xe9nergies renouvelables et la propagation du COVID-19. Les utilisateurs d\xe9battent de l'aspect pratique de la transition vers les \xe9nergies renouvelables, du fardeau financier que repr\xe9sente l'imp\xf4t pour les super-riches et de l'instrumentalisation de la gentillesse et de la tol\xe9rance en politique. La r\xe9putation de Tesla, le traitement de ses employ\xe9s et sa vision de l'avenir sont \xe9galement abord\xe9s. Le r\xe9dacteur doit identifier le message principal et \xe9viter les pr\xe9jug\xe9s politiques ou religieux."]}),"\n",(0,n.jsx)(s.h2,{id:"les-employ\xe9s-de-tesla-ont-partag\xe9-des-images-sensibles-enregistr\xe9es-par-les-voitures-des-clients",children:"Les employ\xe9s de Tesla ont partag\xe9 des images sensibles enregistr\xe9es par les voitures des clients"}),"\n",(0,n.jsxs)(s.p,{children:["(Original) (",(0,n.jsx)(s.a,{href:"https://www.reuters.com/technology/tesla-workers-shared-sensitive-images-recorded-by-customer-cars-2023-04-06/",children:"https://www.reuters.com/technology/tesla-workers-shared-sensitive-images-recorded-by-customer-cars-2023-04-06/"}),").\nLes employ\xe9s de Tesla ont partag\xe9 des vid\xe9os sensibles captur\xe9es par les cam\xe9ras des voitures des clients entre 2019 et 2022, selon des entretiens men\xe9s par Reuters avec neuf anciens employ\xe9s de Tesla. Les accidents, la rage au volant et les situations embarrassantes figuraient parmi les vid\xe9os partag\xe9es via le syst\xe8me de messagerie interne de Tesla, certaines publiquement. L'avis de confidentialit\xe9 de l'entreprise souligne l'assurance de l'anonymat des enregistrements des cam\xe9ras qui ne sont pas li\xe9s aux clients ou \xe0 leurs v\xe9hicules, mais certains anciens employ\xe9s ont parl\xe9 d'une \"violation de la vie priv\xe9e\". Tesla a r\xe9pondu aux pr\xe9occupations en mati\xe8re de protection des donn\xe9es en apportant des modifications au mode \"Sentry\", notamment en faisant clignoter les phares des voitures en stationnement pour avertir les passants qu'ils sont susceptibles d'\xeatre surveill\xe9s. Reuters affirme que toutes les citations seront retard\xe9es et fournit des liens pour des corrections et des commentaires sur le site."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35468855",children:"Discussion Service"}),".\nLes employ\xe9s de Tesla ont partag\xe9 des images sensibles enregistr\xe9es par les voitures des clients sans mesures de protection de la vie priv\xe9e. Les r\xe9glementations en mati\xe8re de protection de la vie priv\xe9e doivent \xeatre appliqu\xe9es avec des cons\xe9quences s\xe9rieuses, et les entreprises doivent mettre en place des mesures de protection de la vie priv\xe9e d\xe8s le d\xe9part. Des anecdotes mettent en \xe9vidence un manque de protection de la vie priv\xe9e dans diverses entreprises et startups, et l'absence de lois sur la protection de la vie priv\xe9e en Inde est critiqu\xe9e. La confidentialit\xe9 des donn\xe9es n'est pas enti\xe8rement s\xfbre, et les employ\xe9s peuvent voir et utiliser \xe0 mauvais escient des donn\xe9es priv\xe9es. Les normes allemandes en mati\xe8re de protection de la vie priv\xe9e ne sont pas parfaites, mais les autorit\xe9s charg\xe9es de la protection des donn\xe9es s'int\xe9resseraient \xe0 toute violation de donn\xe9es par les constructeurs automobiles en raison de l'application du GDPR. Les v\xe9hicules connect\xe9s suscitent des inqui\xe9tudes en mati\xe8re de protection de la vie priv\xe9e, mais certains font remarquer que des capacit\xe9s de suivi similaires existent dans les v\xe9hicules autres que les v\xe9hicules \xe9lectriques. Des rapports sugg\xe8rent que certains pr\xeateurs ont plac\xe9 des dispositifs de suivi sur les voitures, bien qu'il ne soit pas clair s'ils vendent les donn\xe9es."]}),"\n",(0,n.jsx)(s.h2,{id:"buck2--notre-syst\xe8me-de-construction-open-source",children:"Buck2 : Notre syst\xe8me de construction open source"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://engineering.fb.com/2023/04/06/open-source/buck2-open-source-large-scale-build-system/",children:"Original"}),".\nMeta publie Buck2, un syst\xe8me de construction open-source sur GitHub, \xe9crit en Rust. Buck2 s\xe9pare les r\xe8gles de base et les r\xe8gles sp\xe9cifiques au langage, avec des tests internes indiquant des constructions deux fois plus rapides que Buck1, un parall\xe9lisme accru, et une console de sortie redessin\xe9e. Buck2 pourrait convenir \xe0 des projets multi-langues de taille mod\xe9r\xe9e, con\xe7u avec des fonctionnalit\xe9s avanc\xe9es pour la performance et des fonctionnalit\xe9s de d\xe9pendances expressives et dynamiques. Meta partage des projets technologiques open source, notamment en mati\xe8re d'IA, de donn\xe9es, de d\xe9veloppement, de front-end, de langages, de plateformes, de s\xe9curit\xe9 et de RV, sans qu'aucune mise \xe0 jour ou publication notable ne soit mentionn\xe9e."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35470371",children:"Discussion Service"}),".\nLe syst\xe8me de construction open-source Buck2 de Facebook attire l'attention gr\xe2ce \xe0 son moteur de calcul incr\xe9mental et \xe0 la prise en charge de Windows. Les utilisateurs de Discussion Service discutent d'autres outils de construction, y compris Waf, TensorFlow et Py_wheel, en soulignant les d\xe9fis li\xe9s \xe0 la gestion de grandes bases de code. Buck2 supprime la d\xe9pendance \xe0 la JVM de Buck1 en la r\xe9\xe9crivant en Rust. Buck2 et Bazel sont des syst\xe8mes de construction multi-langues avec des constructions reproductibles et des capacit\xe9s d'int\xe9gration. L'article sugg\xe8re d'utiliser le bon outil pour le bon travail et de se concentrer sur les points forts d'un outil. Certains utilisateurs affirment que la compilation statique ajoute de la complexit\xe9, tandis que d'autres d\xe9fendent les avantages des binaires li\xe9s statiquement."]}),"\n",(0,n.jsx)(s.h2,{id:"mariadbcom-est-mort-vive-mariadborg",children:"Mariadb.com est mort, vive MariaDB.org"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://medium.com/@imashadowphantom/mariadb-com-is-dead-long-live-mariadb-org-b8a0ca50a637",children:"Original"}),".\nMariaDB.com, l'entit\xe9 commerciale, est confront\xe9e \xe0 des \xe9checs dus \xe0 une mauvaise gestion, au racisme, \xe0 des accusations de sexisme et \xe0 des violations du droit du travail. Monty, le fondateur, a \xe9t\xe9 \xe9cart\xe9 du conseil d'administration en juillet 2022, et la prise de contr\xf4le hostile du PDG Michael Howard a entra\xeen\xe9 une baisse de la valeur des actions. Les documents d\xe9pos\xe9s aupr\xe8s de la SEC indiquent que MariaDB pourrait fermer ses portes, confront\xe9e \xe0 des probl\xe8mes de r\xe9tention et de recrutement du personnel en raison de sa r\xe9putation. Il est conseill\xe9 aux employ\xe9s d'organiser des entretiens avec d'autres entreprises, tout en faisant l'\xe9loge de MariaDB.org et de l'open source."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35467243",children:"Discussion Service"}),".\nLa fermeture de MariaDB.com entra\xeene des soup\xe7ons d'instabilit\xe9 financi\xe8re. Les all\xe9gations de partialit\xe9 et les accusations non \xe9tay\xe9es \xe0 l'encontre de MariaDB Corp. sont accueillies avec scepticisme. L'opinion publique est divis\xe9e sur l'avenir de MariaDB.org. Le fil de discussion de Hacker News discute des all\xe9gations de discrimination et passe \xe0 une comparaison entre MariaDB et Postgres. MariaDB Corporation d\xe9pose le bilan, l'impact sur le d\xe9veloppement est incertain. L'action de MariaDB PLC chute de pr\xe8s de 70% depuis son introduction en bourse, les analystes s'inqui\xe8tent de l'inexp\xe9rience de la direction et des changements dans l'industrie. La perte d'un proc\xe8s de 20 millions de dollars et la fusion de SkySQL contribuent aux difficult\xe9s financi\xe8res. Les inqui\xe9tudes concernant le d\xe9veloppement futur ne sont pas fond\xe9es en raison des sponsors de l'entreprise."]}),"\n",(0,n.jsx)(s.h2,{id:"show-discussion-service--pomodoro-une-application-web-adapt\xe9e-aux-tdah",children:"Show Discussion Service : Pomodoro, une application web adapt\xe9e aux TDAH"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://brainpls.work/",children:"Original"}),".\nMalheureusement, comme il ne s'agit que d'un commentaire d'une ligne, il n'y a pas assez d'informations pour fournir un r\xe9sum\xe9 concis."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35471129",children:"Discussion Service"}),".\n'Brainpls.work' Pomodoro-based timer for ADHD support criticized as web-based. Des suggestions ont \xe9t\xe9 faites pour un dispositif de minuterie plus intelligent et des am\xe9liorations de l'application du navigateur. Une nouvelle application de minutage de l'attention et du flux est publi\xe9e sur Github, pr\xe9f\xe9r\xe9e en tant qu'application native. Les utilisateurs font l'\xe9loge de l'application de cartes flash personnelles pour le suivi des progr\xe8s. Les commentaires incluent l'ajout de notifications sonores, le marquage des distractions et l'affichage de l'heure locale. Le d\xe9veloppeur de l'application pourrait souffrir de TDAH."]}),"\n",(0,n.jsx)(s.h2,{id:"meta-lance-un-nouvel-outil-de-segmentation-de-photos-bas\xe9-sur-lia-pour-tout-le-monde",children:"Meta lance un nouvel outil de segmentation de photos bas\xe9 sur l'IA pour tout le monde"}),"\n",(0,n.jsxs)(s.p,{children:["(",(0,n.jsx)(s.a,{href:"https://arstechnica.com/information-technology/2023/04/meta-introduces-ai-model-that-can-isolate-and-mask-objects-within-images/",children:"https://arstechnica.com/information-technology/2023/04/meta-introduces-ai-model-that-can-isolate-and-mask-objects-within-images/"}),").\nMeta a d\xe9velopp\xe9 un nouveau mod\xe8le de segmentation d'image appel\xe9 SAM qui peut isoler n'importe quel objet dans des images ou des vid\xe9os sur commande. SAM vise \xe0 d\xe9mocratiser le processus de segmentation des images en r\xe9duisant la n\xe9cessit\xe9 d'une formation et d'une expertise sp\xe9cialis\xe9es. Cette technologie est adapt\xe9e \xe0 la compr\xe9hension du contenu des pages web, \xe0 l'\xe9dition d'images et aux applications de r\xe9alit\xe9 augment\xe9e. SAM se distingue par sa capacit\xe9 \xe0 identifier des objets non pr\xe9sents dans son ensemble de donn\xe9es de formation et par son approche partiellement ouverte. En outre, Meta a cr\xe9\xe9 un ensemble de donn\xe9es appel\xe9 SA-1B qui comprend 11 millions d'images et 1,1 milliard de masques de segmentation qui seront mis \xe0 disposition \xe0 des fins de recherche sous une licence Apache 2.0."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35468304",children:"Discussion Service"}),".\nMeta lance un outil de segmentation de photos bas\xe9 sur l'IA en faisant l'\xe9loge de l'ouverture et du d\xe9veloppement de l'IA. Certains s'inqui\xe8tent de la viabilit\xe9 de la plateforme. Le mod\xe8le a \xe9t\xe9 entra\xeen\xe9 sur 12,6 millions d'images libres. Les utilisateurs critiquent le titre trompeur de l'article et les outils de segmentation existants. Aucun rapport avec l'extension Chrome ou les applications YC."]}),"\n",(0,n.jsx)(s.h2,{id:"ce-qui-se-passe-en-cas-de-fuite-dinformations-didentification-aws-et-comment-aws-minimise-les-d\xe9g\xe2ts",children:"Ce qui se passe en cas de fuite d'informations d'identification AWS et comment AWS minimise les d\xe9g\xe2ts"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://xebia.com/blog/what-happens-when-you-leak-aws-credentials-and-how-aws-minimizes-the-damage/",children:"Original"}),".\nUn utilisateur d'AWS a intentionnellement divulgu\xe9 ses identifiants AWS sur un d\xe9p\xf4t GitHub public pour voir ce qui se passerait. Dans la minute qui a suivi la fuite, AWS a ajout\xe9 une \"politique de quarantaine\" au compte de l'utilisateur et l'a inform\xe9 par e-mail des instructions \xe0 suivre pour s\xe9curiser son compte. Un acteur malveillant a rapidement effectu\xe9 des appels API automatis\xe9s avec les informations d'identification divulgu\xe9es, mais sans succ\xe8s en raison des autorisations limit\xe9es. AWS utilise un service GitHub Secrets Scanning pour d\xe9tecter rapidement les fuites d'informations d'identification et y r\xe9pondre. Pour \xe9viter les fuites d'informations d'identification, les utilisateurs peuvent ex\xe9cuter des analyses avant validation localement ou ajouter un scanner de secrets \xe0 leur pipeline CI/CD."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35466675",children:"Discussion Service"}),".\nUn utilisateur de Discussion Service a mis en place un projet pour faire fuir automatiquement les secrets AWS et d\xe9clencher des processus d'analyse. Il est frustrant d'effectuer une rotation des cl\xe9s lorsqu'il y en a plusieurs dans un compte. AWS invalide les tokens dans les r\xe9f\xe9rentiels publics, mais les escrocs peuvent d\xe9j\xe0 y avoir acc\xe8s. Il est conseill\xe9 aux utilisateurs d'AWS de consulter l'\xe9quipe avant de r\xe9voquer des cl\xe9s en production. Le support AWS doit \xeatre contact\xe9 le plus rapidement possible apr\xe8s une attaque. Une s\xe9curit\xe9 suppl\xe9mentaire peut \xeatre ajout\xe9e en limitant l'utilisation des cl\xe9s \xe0 certaines IP. Un script ou un hook git peut emp\xeacher l'envoi d'informations d'identification. L'intention de programmation du scanner n'est pas claire."]}),"\n",(0,n.jsx)(s.h2,{id:"gource---animez-votre-historique-git",children:"Gource - Animez votre historique Git"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://gource.io/",children:"Original"}),".\nGource est un g\xe9n\xe9rateur graphique d'arbres anim\xe9s pour les r\xe9pertoires de projets logiciels sur lesquels les d\xe9veloppeurs peuvent travailler. L'outil dispose d'un support de log int\xe9gr\xe9 pour Git, Mercurial, Bazaar, et SVN, et peut analyser les logs faits par des outils tiers pour les d\xe9p\xf4ts CVS. Gource dispose d'une documentation compl\xe8te, d'exemples et de contr\xf4les sur sa page wiki, qui incluent de nouvelles fonctionnalit\xe9s, polices, filtres et options comme l'option --high-dpi, l'option --file-idle-time-at-end ou l'option --fixed-user-size. Gource 0.54 est la derni\xe8re version, qui inclut le support exp\xe9rimental de Wayland et des corrections de bugs sur Apple M1. Il existe d'autres outils similaires comme Logstalgia, consid\xe9r\xe9 comme un outil utile de visualisation des journaux d'acc\xe8s aux serveurs web. Si vous aimez Gource, vous pouvez montrer votre appr\xe9ciation et faire un don \xe0 son auteur pour encourager le d\xe9veloppement futur de ce projet et d'autres projets open-source."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35471420",children:"Discussion Service"}),".\nGource, un outil permettant d'animer l'historique Git, est appr\xe9ci\xe9 pour d\xe9terminer la structure d'un projet, les tendances d'\xe9dition et les mod\xe8les de travail, et est souvent utilis\xe9 pour une visualisation amusante. Les Redditors l'utilisent pour visualiser l'activit\xe9 des commentaires et les remaniements de code. Certaines entreprises l'affichent m\xeame publiquement. Certains peinent \xe0 trouver des utilisations pratiques, mais le trouvent gratifiant en tant qu'outil de r\xe9flexion. Il est esth\xe9tiquement agr\xe9able pour beaucoup."]}),"\n",(0,n.jsx)(s.h2,{id:"show-discussion-service--g\xe9n\xe9rer-des-id\xe9es-de-startups-bas\xe9es-sur-les-commentaires-discussion-service",children:"Show Discussion Service : G\xe9n\xe9rer des id\xe9es de startups bas\xe9es sur les commentaires Discussion Service"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://hn-ideas.tjcx.me/",children:"Original"}),".\nPr\xe9sentation d'un nouvel outil en ligne qui g\xe9n\xe8re des id\xe9es de cr\xe9ation d'entreprise \xe0 partir de sujets tir\xe9s des commentaires publi\xe9s sur Hacker News. D\xe9velopp\xe9e par une personne nomm\xe9e tjcx, la plateforme permet aux utilisateurs d'entrer un sujet et de recevoir une id\xe9e de startup al\xe9atoire bas\xe9e sur les commentaires li\xe9s \xe0 ce sujet. Cette invention peut s'av\xe9rer utile pour donner du pouvoir aux entrepreneurs et promouvoir l'innovation."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35467917",children:"Discussion Service"}),".\nUn nouveau g\xe9n\xe9rateur d'id\xe9es de d\xe9marrage a \xe9t\xe9 cr\xe9\xe9 \xe0 partir des commentaires de Discussion Service. Les id\xe9es vont du s\xe9rieux au sarcastique, y compris un service d'abonnement \xe0 du sang de ch\xe8vre et l'embauche de tueurs \xe0 gages. Les commentaires se moquent des id\xe9es, mais sugg\xe8rent \xe9galement des plateformes pour l'intelligence artificielle et la m\xe9decine personnalis\xe9e. D'autres suggestions portent sur des applications de remise en forme, des dispositifs de surveillance de la temp\xe9rature et la RV pour la surveillance des animaux de compagnie. Les utilisateurs de Discussion Service sugg\xe8rent un large \xe9ventail d'id\xe9es de startups, y compris des id\xe9es controvers\xe9es telles que des poup\xe9es sexuelles ressemblant \xe0 des enfants et de la viande humaine cultiv\xe9e en laboratoire. Les r\xe9sultats sont mitig\xe9s : certains trouvent cela amusant, d'autres pas tr\xe8s utile. L'exactitude est critiqu\xe9e et les commentaires politiques ou religieux sont d\xe9courag\xe9s."]}),"\n",(0,n.jsx)(s.h2,{id:"devops-utilise-un-mod\xe8le-de-capacit\xe9-pas-un-mod\xe8le-de-maturit\xe9",children:"DevOps utilise un mod\xe8le de capacit\xe9, pas un mod\xe8le de maturit\xe9"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://octopus.com/blog/devops-uses-capability-not-maturity",children:"Original"}),".\nSelon Steve Fenton, DevOps devrait utiliser un mod\xe8le de capacit\xe9 et non un mod\xe8le de maturit\xe9. Contrairement \xe0 un mod\xe8le de maturit\xe9, l'approche est bas\xe9e sur les r\xe9sultats et encourage l'exp\xe9rimentation des outils et des processus. Bas\xe9e sur le SEM, personnalisable et dynamique, elle permet de r\xe9aliser des gains incr\xe9mentaux en identifiant les capacit\xe9s. Les mod\xe8les de maturit\xe9 peuvent \xeatre rigides, standardis\xe9s et ne pas prendre en compte les d\xe9fis uniques de l'entreprise. Le mod\xe8le de capacit\xe9 relie les caract\xe9ristiques aux r\xe9sultats plus larges du syst\xe8me. Le mod\xe8le structurel est \xe9crasant, mais doit \xeatre utilis\xe9 pour une am\xe9lioration continue."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35466718",children:"Discussion Service"}),'.\nDevOps a transform\xe9 les r\xf4les de l\'\xe9quipe de d\xe9veloppement et a pouss\xe9 les niveaux de comp\xe9tences des administrateurs syst\xe8me \xe0 la hausse. Certains sugg\xe8rent des termes alternatifs comme "ing\xe9nierie de plateforme". Le mod\xe8le de capacit\xe9 bas\xe9 sur des mesures est critiqu\xe9 comme \xe9tant un argument de vente, appel \xe0 des capacit\xe9s significatives. Cultiver une culture de la nouveaut\xe9 pour le d\xe9veloppement commercial.']}),"\n",(0,n.jsx)(s.h2,{id:"laugmentation-de-la-capacit\xe9-du-r\xe9seau-\xe9lectrique-nest-pas-une-t\xe2che-simple",children:"L'augmentation de la capacit\xe9 du r\xe9seau \xe9lectrique n'est pas une t\xe2che simple."}),"\n",(0,n.jsxs)(s.p,{children:["(",(0,n.jsx)(s.a,{href:"https://www.economist.com/technology-quarterly/2023/04/05/adding-capacity-to-the-electricity-grid-is-not-a-simple-task",children:"https://www.economist.com/technology-quarterly/2023/04/05/adding-capacity-to-the-electricity-grid-is-not-a-simple-task"}),").\nLe r\xe9seau \xe9lectrique est confront\xe9 \xe0 des difficult\xe9s d'int\xe9gration des sources renouvelables, peu de fournisseurs \xe9tant dispos\xe9s \xe0 augmenter la capacit\xe9 des transformateurs. Une r\xe9glementation conservatrice et des connexions insuffisantes au r\xe9seau limitent la part de march\xe9 des \xe9nergies renouvelables, ce qui entra\xeene des retards et des incertitudes dans les nouveaux projets. Les r\xe9gulateurs reconnaissent la n\xe9cessit\xe9 de connexions \xe0 long terme pour la d\xe9carbonisation du r\xe9seau, avec de nouvelles r\xe9glementations pour soutenir les projets d'\xe9nergie renouvelable. L'Inde pr\xe9voit de raccorder 500 GW de capacit\xe9 renouvelable d'ici \xe0 2030, tandis que la Chine b\xe9n\xe9ficie de l'expansion r\xe9cente de son r\xe9seau. Toutefois, l'optimisation de la gestion des files d'attente et des proc\xe9dures de planification reste cruciale, car la construction d'infrastructures de r\xe9seau doit trouver un \xe9quilibre d\xe9licat."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35463182",children:"Discussion Service"}),".\nL'augmentation de la capacit\xe9 du r\xe9seau \xe9lectrique se heurte \xe0 des probl\xe8mes de permis, de l\xe9gislation environnementale, de propri\xe9t\xe9, de domaine \xe9minent et de recherche de propri\xe9taires non enregistr\xe9s. Les pays sont confront\xe9s \xe0 des probl\xe8mes de r\xe9seau uniques, notamment le r\xe9seau \xe9lectrique n\xe9glig\xe9 de l'Afrique du Sud et la capacit\xe9 du r\xe9seau des Pays-Bas qui ne peut pas suivre les investissements. Au Royaume-Uni, d'anciennes infrastructures de r\xe9seau sont r\xe9utilis\xe9es pour de nouveaux parcs \xe9oliens en mer, mais de nombreux projets verts sont pr\xe9vus pour les ann\xe9es 2030. La stabilit\xe9 du r\xe9seau par rapport \xe0 la promotion des sources d'\xe9nergie renouvelables et la n\xe9cessit\xe9 de l'hydrog\xe8ne pour le stockage de l'\xe9nergie sont discut\xe9es. Les d\xe9fis pos\xe9s par les \xe9nergies renouvelables comprennent la surconstruction, le stockage et la connectivit\xe9 du r\xe9seau. Les Sud-Africains subissent moins de pannes d'\xe9lectricit\xe9 que des pays comme l'Allemagne et l'Autriche. La Chine est \xe0 la pointe du progr\xe8s en mati\xe8re de transmission de courant continu \xe0 tr\xe8s haute tension. Les \xe9nergies renouvelables n'ont jamais pos\xe9 de probl\xe8me pour les r\xe9seaux, m\xeame si l'inertie synth\xe9tique et la gestion des baisses soudaines de l'offre restent un d\xe9fi."]}),"\n",(0,n.jsx)(s.h2,{id:"annonce-de-wcgi--webassembly-et-cgi",children:"Annonce de WCGI : WebAssembly et CGI"}),"\n",(0,n.jsxs)(s.p,{children:["(Original) (",(0,n.jsx)(s.a,{href:"https://wasmer.io/posts/announcing-wcgi",children:"https://wasmer.io/posts/announcing-wcgi"}),").\nWasmer a pr\xe9sent\xe9 WCGI, une technologie qui combine la puissance de WebAssembly et la simplicit\xe9 de CGI pour le d\xe9veloppement c\xf4t\xe9 serveur. Elle permet de r\xe9utiliser les applications CGI existantes, de cr\xe9er des paquets ultra-petits contenant uniquement la logique commerciale et les actifs statiques, et d'ex\xe9cuter le code WebAssembly dans un bac \xe0 sable. Il garantit une efficacit\xe9, une s\xe9curit\xe9 et une flexibilit\xe9 accrues dans le d\xe9veloppement c\xf4t\xe9 serveur et a le potentiel de remodeler le paysage des applications sans serveur. Les d\xe9veloppeurs web peuvent cr\xe9er des applications WCGI avec Rust et PHP en les compilant vers Wasm, et les serveurs WCGI peuvent \xeatre ex\xe9cut\xe9s \xe0 l'aide de la CLI de Wasmer. Wasmer travaille en permanence \xe0 l'\xe9largissement des possibilit\xe9s de WCGI."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35469276",children:"Discussion Service"}),".\nWasmer.io annonce WCGI, permettant une int\xe9gration transparente avec les serveurs existants ; Java Servlets vs. open standards ; WebAssembly solutions outside the browser. Les applets Java, GWT et la JVM sont abord\xe9s. WCGI offre une isolation de la m\xe9moire, une capacit\xe9 de sortie CGI et \xe9limine le besoin de variables d'environnement. Wordpress teste les performances de WCGI. Les d\xe9veloppeurs utilisent WASM et Wasmer pour l'inclusion de code natif, ce qui r\xe9duit les d\xe9lais et am\xe9liore la portabilit\xe9. Allocation de ressources d'applications hautement s\xe9curis\xe9es et contr\xf4le des modules. La vitesse d'ex\xe9cution est plus lente avec WebAssembly qu'avec le code natif."]}),"\n",(0,n.jsx)(s.h2,{id:"json-vs-xml",children:"JSON vs. XML"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://corecursive.com/json-vs-xml-douglas-crockford/#",children:"Original"}),".\nDoug Crockford, cr\xe9ateur de JSON, raconte son histoire dans le podcast CoRecursive et \xe9voque ses batailles contre XML, l'histoire de JavaScript et le r\xf4le qu'il a jou\xe9 pour faire de JSON une norme. Il revient \xe9galement sur sa carri\xe8re et encourage les d\xe9veloppeurs \xe0 adopter de nouveaux paradigmes. Les utilisateurs de Discussion Service partagent leur exp\xe9rience et leurs r\xe9flexions sur divers sujets li\xe9s \xe0 la technologie. Dans l'ensemble, ces articles offrent des informations pr\xe9cieuses aux professionnels d\xe9sireux d'approfondir leurs connaissances."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35467711",children:"Discussion Service"}),".\nLes experts d\xe9battent des avantages et des inconv\xe9nients de XML et de JSON, certains pr\xe9f\xe9rant XML pour les donn\xe9es complexes tandis que d'autres sugg\xe8rent JSON en raison de sa simplicit\xe9 et de son adoption g\xe9n\xe9ralis\xe9e. Douglas Crockford est v\xe9n\xe9r\xe9 par les programmeurs et occupe une place particuli\xe8re dans le c\u0153ur des amateurs de JS. Les utilisateurs discutent des avantages et des inconv\xe9nients des diff\xe9rents formats de donn\xe9es et langages de programmation, sans qu'il y ait de solution claire \xe0 leurs compromis inh\xe9rents. Malgr\xe9 le d\xe9bat, les diff\xe9rents formats existent pour une raison et doivent \xeatre choisis en fonction des besoins. Adam Bosworth affirme que l'essor fulgurant du HTML est d\xfb \xe0 ses limites, et non \xe0 son absence, et que le XML est trop complexe pour les utilisateurs de tous les jours."]}),"\n",(0,n.jsx)(s.h2,{id:"site-web-h\xe9berg\xe9-sur-un-serveur-linux-vieux-de-24-ans",children:"Site web h\xe9berg\xe9 sur un serveur Linux vieux de 24 ans."}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://raq.serialport.org/",children:"Original"}),".\nComme il n'y a pas de contenu textuel brut, je ne suis pas en mesure de fournir un r\xe9sum\xe9 pour cette t\xe2che."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35468637",children:"Discussion Service"}),".\nUn serveur Linux vieux de 24 ans fonctionne toujours avec NetBSD et Apache, h\xe9bergeant un site web. Les utilisateurs se souviennent des technologies web d\xe9pass\xe9es, certains sugg\xe9rant de nouvelles fa\xe7ons d'impl\xe9menter les livres d'or ou les compteurs de vues. Ils discutent \xe9galement de l'acc\xe8s simultan\xe9 aux fichiers et de l'attitude de la soci\xe9t\xe9 \xe0 l'\xe9gard de la programmation. L'h\xe9bergement d'un site web sur du mat\xe9riel obsol\xe8te n'est pas pratique pour diffuser des pages \xe0 l'heure actuelle. Certains trouvent qu'il est difficile d'acc\xe9der au serveur \xe0 cause de cloudflare."]}),"\n",(0,n.jsx)(s.h2,{id:"est-ce-ma-faute-si-vous-ne-pouvez-pas-supporter-la-v\xe9rit\xe9--2019",children:"Est-ce ma faute si vous ne pouvez pas supporter la v\xe9rit\xe9 ? (2019)"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://agileotter.blogspot.com/2019/09/is-it-my-fault-you-cant-handle-truth.html",children:"Original"}),".\nL'article met en garde contre les dangers d'une rationalit\xe9 excessive, soulignant qu'il est parfois plus important d'\xeatre utile que d'avoir raison. Il explique comment les individus trop rationnels peuvent manquer d'empathie et cr\xe9er des jeux de pouvoir. L'article cite un exemple d'approche positive de r\xe9solution de probl\xe8mes et interroge les lecteurs sur le fait de se cacher derri\xe8re la rationalit\xe9 pour \xe9viter la responsabilit\xe9. Les commentaires de la discussion sur Hacker News portent sur des sujets tels que la productivit\xe9 et la m\xe9thodologie agile, o\xf9 les utilisateurs abordent la question de la rationalit\xe9 et du dysfonctionnement des entreprises. Un utilisateur sugg\xe8re un livre sur la m\xe9thode agile comme r\xe9f\xe9rence. Aucune nouvelle technologie ou version n'a \xe9t\xe9 mentionn\xe9e."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35475482",children:"Discussion Service"}),".\nUn article met l'accent sur le fait de guider les gens plut\xf4t que de leur dire la v\xe9rit\xe9, car les faits sont souvent inefficaces. Les utilisateurs de Discussion Service discutent de l'importance de l'empathie et du contexte, et s'interrogent sur la possibilit\xe9 de tirer du plaisir de la col\xe8re. Les experts d\xe9battent de l'\xe9quilibre entre l'honn\xeatet\xe9 et la gentillesse, et de la n\xe9cessit\xe9 de l'empathie, du respect et de la rigueur scientifique. Le d\xe9bat porte sur l'objectif de la science, la recherche de la v\xe9rit\xe9 et la th\xe9orie des jeux. Une communication efficace de la v\xe9rit\xe9 exige du tact, du temps et l'\xe9tablissement de relations, car la n\xe9gligence conduit \xe0 la cruaut\xe9 et aux luttes de pouvoir. Certains affirment que, dans certains contextes, la v\xe9rit\xe9 objective peut \xeatre irrespectueuse et qu'une v\xe9rit\xe9 unique est imparfaite."]}),"\n",(0,n.jsx)(s.h2,{id:"les-cordes-en-do-et-ma-lente-descente-vers-la-folie",children:"Les cordes en do et ma lente descente vers la folie"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://www.deusinmachina.net/p/c-strings-and-my-slow-descent-to",children:"Original"}),".\nDiego Crespo traite de la manipulation des cha\xeenes de caract\xe8res en C et des fonctions courantes telles que strcpy et strlen, ainsi que des probl\xe8mes potentiels li\xe9s \xe0 l'utilisation de ces fonctions. Les d\xe9fis pos\xe9s par le travail avec des langues non latines, en particulier l'Unicode et l'encodage UTF-8, sont d\xe9taill\xe9s avec des solutions de contournement possibles. L'importance de la prudence lors du travail avec les cha\xeenes C, afin d'\xe9viter les comportements ind\xe9finis et les attaques potentielles, est soulign\xe9e. Crespo note \xe9galement que le C++ \xe9vite certains de ces probl\xe8mes en traitant les cha\xeenes comme des objets. Les lecteurs sont invit\xe9s \xe0 consulter les comptes de m\xe9dias sociaux de l'auteur et ses articles sur les langages de programmation et le codage de bas niveau."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35467367",children:"Discussion Service"}),".\nLes utilisateurs de Discussion Service discutent des probl\xe8mes de s\xe9curit\xe9 inh\xe9rents au traitement des cha\xeenes de caract\xe8res en C, sugg\xe8rent d'utiliser d'autres biblioth\xe8ques et soulignent la n\xe9cessit\xe9 d'une meilleure gestion de la m\xe9moire. La praticit\xe9 du langage C pour le traitement des cha\xeenes de caract\xe8res est d\xe9battue, certains recommandant l'utilisation d'allocateurs ou de conteneurs. Les biblioth\xe8ques C par d\xe9faut sont critiqu\xe9es pour leur inefficacit\xe9, et les utilisateurs sugg\xe8rent de renommer la fonction strlen pour une meilleure lisibilit\xe9. Les commentaires couvrent \xe9galement les bogues caus\xe9s par strncpy() et les nuances de l'Unicode. Les enthousiastes du langage C d\xe9fendent l'acc\xe8s et le contr\xf4le du langage, tandis que d'autres le trouvent trop complexe, et discutent des diff\xe9rentes m\xe9thodes de manipulation des cha\xeenes en C. Des conseils sont donn\xe9s pour \xe9viter les pi\xe8ges communs de la manipulation des cha\xeenes en C. La frustration est exprim\xe9e et des biblioth\xe8ques de cha\xeenes de caract\xe8res alternatives aux tableaux simples sont sugg\xe9r\xe9es. Malgr\xe9 la popularit\xe9 du langage C, il manque une solution efficace pour la gestion des cha\xeenes de caract\xe8res."]}),"\n",(0,n.jsx)(s.h2,{id:"mutexprotected--un-mod\xe8le-c-pour-une-concurence-plus-facile",children:"MutexProtected : Un mod\xe8le C++ pour une concurence plus facile"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://awesomekling.github.io/MutexProtected-A-C++-Pattern-for-Easier-Concurrency/",children:"Original"}),".\nL'article explique les d\xe9fis pos\xe9s par la programmation d'applications concurrentes utilisant des verrous et pr\xe9sente un mod\xe8le C++ appel\xe9 MutexProtected qui simplifie ce processus. L'auteur utilise un exemple en C pour d\xe9montrer la n\xe9cessit\xe9 de MutexProtected et pr\xe9pare un exemple d\xe9pouill\xe9. L'article pr\xe9sente ensuite une classe RAII C++ pour r\xe9soudre le probl\xe8me du d\xe9verrouillage oubli\xe9 du mutex, mais montre ses lacunes. L'auteur pr\xe9sente ensuite MutexProtected comme une construction puissante qui combine un mutex et un type de donn\xe9es pour garantir un acc\xe8s concurrent correct aux donn\xe9es. L'article se termine par l'introduction de MemoizedTreeMap, une impl\xe9mentation d'une carte arborescente qui utilise MutexProtected pour assurer la s\xe9curit\xe9 des threads."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35464152",children:"Discussion Service"}),".\nMutexProtected est un mod\xe8le C++ pour une concurrence facile comme les mutex de Rust. Boost.synchronized est complexe, mais peut \xeatre utilis\xe9 en-t\xeate seulement. Les commentaires sugg\xe8rent des lambdas et des verrous et d\xe9verrouillages explicites ou de style RAII, ainsi que scoped_lock pour des verrous multiples. Les experts d\xe9battent des mutex par rapport aux canaux pour la concurrence."]}),"\n",(0,n.jsx)(s.h2,{id:"clarence-thomas-et-le-milliardaire",children:"Clarence Thomas et le milliardaire"}),"\n",(0,n.jsxs)(s.p,{children:["(Original) (",(0,n.jsx)(s.a,{href:"https://www.propublica.org/article/clarence-thomas-scotus-undisclosed-luxury-travel-gifts-crow",children:"https://www.propublica.org/article/clarence-thomas-scotus-undisclosed-luxury-travel-gifts-crow"}),").\nProPublica rapporte que le juge Clarence Thomas aurait accept\xe9 des voyages de luxe de la part du donateur r\xe9publicain Harlan Crow pendant plus de vingt ans, sans en faire \xe9tat dans ses d\xe9clarations financi\xe8res annuelles, ce qui soul\xe8ve des questions d'ordre \xe9thique. Harlan Crow, qui a d\xe9pens\xe9 des millions pour la politique conservatrice, poss\xe8de un yacht et un jet priv\xe9 \xe0 bord desquels Thomas a voyag\xe9, et l'a accueilli dans son ranch texan et dans un centre de vill\xe9giature priv\xe9. L'acc\xe8s de Crow \xe0 la justice s'\xe9tend \xe0 toute personne que l'homme d'affaires choisit d'inviter, ce qui pourrait constituer une violation des lois sur la divulgation d'informations. Le guide d'\xe9thique actualis\xe9 pour les juges pr\xe9cise que la divulgation est requise pour de tels s\xe9jours, y compris un voyage en 2021 dans un cimeti\xe8re catholique pr\xe8s de New York o\xf9 une statue en bronze de l'enseignant de Thomas en huiti\xe8me ann\xe9e a \xe9t\xe9 inaugur\xe9e gr\xe2ce au financement de M. Crow."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35467948",children:"Discussion Service"}),".\nUn juge essentiel de la Cour supr\xeame des \xc9tats-Unis pourrait \xeatre impliqu\xe9 dans une affaire de corruption importante, car il pourrait avoir re\xe7u des faveurs illicites de la part d'un milliardaire ; cependant, il est peu probable que ces actions conduisent \xe0 une destitution dans le climat ultra-politique d'aujourd'hui. Si le juge Thomas n'est pas li\xe9 par les r\xe8gles \xe9thiques des juridictions inf\xe9rieures, des mesures l\xe9gales peuvent n\xe9anmoins \xeatre prises, notamment une enqu\xeate du minist\xe8re de la justice ou de l'IRS. La corruption apparente au niveau du pouvoir judiciaire met en \xe9vidence l'influence corruptrice des super-riches sur les institutions gouvernementales, avec un succ\xe8s pr\xe9visible jusqu'\xe0 pr\xe9sent. Bien qu'elles soient manifestement contraires \xe0 la loi, les actions du juge Thomas pourraient ne pas \xeatre sanctionn\xe9es, en partie \xe0 cause du refus de demander des comptes \xe0 ceux qui d\xe9tiennent le pouvoir."]}),"\n",(0,n.jsx)(s.h2,{id:"la-faible-composabilit\xe9-de-rust",children:"La faible composabilit\xe9 de Rust"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://thedav.is/post/rusts-poor-composability/",children:"Original"}),".\nL'auteur discute de la faible composabilit\xe9 de Rust, en soulignant les probl\xe8mes de syntaxe avec les boucles for et les it\xe9rateurs, et comment cela affecte les cas d'utilisation r\xe9els ; l'auteur critique le manque de flexibilit\xe9 et de composabilit\xe9 de Rust, plaidant pour un ralentissement du d\xe9veloppement du langage pour se concentrer sur l'ergonomie ; l'auteur mentionne le travail en cours sur les mots-cl\xe9s g\xe9n\xe9riques et les r\xe9f\xe9rences pour am\xe9liorer la composabilit\xe9."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35468168",children:"Discussion Service"}),".\nLes utilisateurs d\xe9battent de la composabilit\xe9 de Rust : certains louent sa polyvalence, d'autres critiquent son manque de flexibilit\xe9 avec les it\xe9rateurs. La puissance de Rust et son syst\xe8me de types sont admir\xe9s, mais certains trouvent sa syntaxe lourde. Les \xe9quipes devraient se concentrer sur l'ergonomie, bien que certains sugg\xe8rent d'utiliser d'autres langages si Rust n'est pas appr\xe9ci\xe9. Le fil Discussion Service discute des pi\xe8ges de la programmation, des fermetures et du mod\xe8le it\xe9ratif de Rust. La syntaxe de Rust, son syst\xe8me d'effets et les limitations des fermetures sont critiqu\xe9s. Des probl\xe8mes de composabilit\xe9 se posent avec les fermetures asynchrones de Rust et le support de la dur\xe9e de vie. Rust exp\xe9rimente le code g\xe9n\xe9rique sur sync+async, alors que Goroutines et Zig disposent de cette fonctionnalit\xe9."]}),"\n",(0,n.jsx)(s.h2,{id:"rep\xe9rer-et-\xe9viter-la-fragmentation-du-tas-dans-les-applications-rust",children:"Rep\xe9rer et \xe9viter la fragmentation du tas dans les applications Rust"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://www.svix.com/blog/heap-fragmentation-in-rust-applications/",children:"Original"}),".\nUn projet Rust a \xe9t\xe9 confront\xe9 \xe0 une croissance de la m\xe9moire sans limite, probablement caus\xe9e par la fragmentation du tas, r\xe9solue en rempla\xe7ant l'allocateur par jemalloc pour un meilleur profil de m\xe9moire. Un benchmark.yml dans le repo du projet teste diff\xe9rentes entr\xe9es. Svix recherche des experts Rust pour un service \xe9volutif pour leur communaut\xe9."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35469632",children:"Discussion Service"}),".\nUn article discute d'\xe9viter la fragmentation du tas dans les applications Rust, et sugg\xe8re que jemalloc peut aider. Les commentaires sugg\xe8rent de compacter le tas, les handles, tcmalloc. Le choix des bonnes options de tas et les compromis sont discut\xe9s. Le marketing des projets open source et l'identification de la fragmentation du tas sont not\xe9s. jemalloc est recommand\xe9 pour l'utilisation \xe9lev\xe9e de la m\xe9moire d'un serveur HTTP en raison de l'allocation par bloc de Rust. L'efficacit\xe9 du syst\xe8me de type de Rust est appr\xe9ci\xe9e, le SLA de 99,999% \xe9tant atteint gr\xe2ce aux tests et aux redondances."]}),"\n",(0,n.jsx)(s.h2,{id:"faites-attention-\xe0-ce-que-vous-testez-ou-d\xe9ployez-sur-vercel",children:"Faites attention \xe0 ce que vous testez ou d\xe9ployez sur Vercel"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://twitter.com/shoeboxdnb/status/1643639119824801793",children:"Original"}),".\nL'article appelle \xe0 la prudence lors des tests ou des d\xe9ploiements sur Vercel, car cela peut entra\xeener l'inscription d'une adresse IP sur la liste noire. Des utilisateurs racontent leur exp\xe9rience personnelle de l'interdiction de l'IP par Vercel, citant des probl\xe8mes de productivit\xe9 et de communication au sein de leur \xe9quipe. Certains sugg\xe8rent que l'interdiction peut \xeatre li\xe9e aux tentatives malavis\xe9es de Vercel de pr\xe9venir les abus. Les solutions consistent \xe0 contacter le service client\xe8le ou \xe0 passer \xe0 un autre service. Un commentaire de Discussion Service souligne l'importance de la s\xe9curit\xe9 de l'infrastructure en nuage et des tests appropri\xe9s."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35474837",children:"Discussion Service"}),".\nVercel r\xe9sout les probl\xe8mes de facturation et explore les limites d'utilisation. Certains critiquent le processus de remboursement. L'optimisation des co\xfbts du cloud est importante. Vercel est compar\xe9 \xe0 AWS App Runner, d'autres alternatives moins ch\xe8res. Serverless peut conduire \xe0 une facturation inattendue."]}),"\n",(0,n.jsx)(s.h2,{id:"linux-64-apporte-des-ajouts-apple-m2-pour-les-macbook-et-mac-mini-2022",children:"Linux 6.4 apporte des ajouts Apple M2 pour les MacBook et Mac Mini 2022"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://www.phoronix.com/news/Apple-M2-Device-Tree-Linux-6.4",children:"Original"}),".\nLes ajouts de l'arbre des p\xe9riph\xe9riques (DT) pour les p\xe9riph\xe9riques M2 d'Apple, y compris MacBook Air, MacBook Pro et Mac Mini, seront ajout\xe9s \xe0 Linux 6.4. Hector Martin, d\xe9veloppeur principal d'Asahi Linux, a soumis les mises \xe0 jour DT du SoC d'Apple pour qu'elles soient mises en file d'attente dans l'arborescence SoC avant l'ouverture de la fen\xeatre de fusion \xe0 la fin du mois. L'ajout de la s\xe9rie Apple M2 Device Tree et la prise en charge du mat\xe9riel essentiel des machines sur le DT apporteront une prise en charge du noyau en amont indispensable pour l'Apple M2. Cependant, l'appareil n'est pas encore utilisable par les utilisateurs finaux, et les personnes souhaitant b\xe9n\xe9ficier de la meilleure exp\xe9rience Linux pour l'Apple M1/M2 devront utiliser une distribution en aval comme Asahi Linux."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35470392",children:"Discussion Service"}),".\nLinux 6.4 ajoute le support Apple M2 pour 2022 MacBook/Mac Mini. Les utilisateurs de Discussion Service comparent la gestion de l'alimentation Linux/MacOS. Asahi Linux n'est pas encore une solution parfaite. Un peu d'enthousiasme mais de la frustration quant \xe0 la qualit\xe9 des commentaires. Les utilisateurs se plaignent de la d\xe9sinformation et des absurdit\xe9s. La qualit\xe9 des discussions s'est d\xe9t\xe9rior\xe9e dans un domaine particulier. Un utilisateur sugg\xe8re de le bloquer. Le reste du fil de discussion ne semble pas affect\xe9."]}),"\n",(0,n.jsx)(s.h2,{id:"illustrations-de-trains-de-maintenance-japonais-invisibles-qui-ne-fonctionnent-que-la-nuit",children:'Illustrations de trains de maintenance japonais "invisibles" qui ne fonctionnent que la nuit'}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://www.spoon-tamago.com/toei-project-unseen-maintenance-trains/",children:"Original"}),".\nL'artiste Masami Onishi a illustr\xe9 la main-d'\u0153uvre japonaise rarement vue des trains de nuit qui effectuent des travaux de maintenance sur les voies et les c\xe2bles \xe9lectriques au petit matin, ce qui garantit un service fluide et ininterrompu tout au long de la journ\xe9e. Les illustrations d\xe9taill\xe9es de ces trains font partie du projet Toei du Bureau m\xe9tropolitain des transports de Tokyo. Elles incluent le \"wagon de meulage des rails\" qui lisse les abrasions sur les rails, et le \"wagon d'inspection \xe9lectrique\" qui \xe9value la hauteur, la tension et l'\xe9tat des lignes \xe9lectriques a\xe9riennes. Les chemins de fer japonais ont un taux de d\xe9raillement remarquablement bas, avec seulement deux incidents de ce type enregistr\xe9s dans tout le pays en 2018."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35474895",children:"Discussion Service"}),".\nIllustrations de trains de maintenance japonais \"invisibles\" ne fonctionnant que la nuit, mis en \xe9vidence par le projet Toei. Des habitants de New York commentent l'insuffisance de la maintenance du m\xe9tro 24 heures sur 24 et 7 jours sur 7, certains bl\xe2mant des m\xe9tiers d\xe9pass\xe9s tels que les op\xe9rateurs de portes. Le contraste entre la propret\xe9 des wagons du m\xe9tro de Tokyo et le manque d'entretien \xe0 New York suscite une discussion sur la m\xe9diocrit\xe9 des infrastructures dans d'autres villes am\xe9ricaines. Les chemins de fer japonais b\xe9n\xe9ficient de l'apport d'investisseurs priv\xe9s et de fonds publics, ce qui contraste avec la perte des transports publics am\xe9ricains, consid\xe9r\xe9s comme un bien public. Le gouvernement m\xe9tropolitain de Tokyo poss\xe8de de nombreux trains, entretenus par des syst\xe8mes d'intelligence artificielle sophistiqu\xe9s, qui devraient \xeatre enti\xe8rement autonomes d'ici 2032. Les heures de pointe \xe0 Tokyo sont moins inconfortables qu'\xe0 Londres ou \xe0 New York, gr\xe2ce aux places r\xe9serv\xe9es."]})]})}function c(e={}){const{wrapper:s}={...(0,a.R)(),...e.components};return s?(0,n.jsx)(s,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);